            let fields = Fields(.object(error.fields))
            switch error.appCode {
            case "ActionLimit": return .actionLimit
            case "AlreadyFought": return .alreadyFought
            case "CornerTaken": return .cornerTaken
            case "InOtherCorner": return .inOtherCorner
            case "MatchLimit": return .matchLimit
            case "MatchNotFinished": return .matchNotFinished
            case "MatchOver": return .matchOver
            case "NotInCorner": return .notInCorner
            case "RoundOver": return try .roundOver(current: fields.decode("current", UInt32.self))
            case "UnknownFighter": return try .unknownFighter(fighter: fields.decode("fighter", String.self))
            case "UnknownMove": return try .unknownMove(kind: fields.decode("kind", String.self))
            case "UnknownSeat": return try .unknownSeat(seat: fields.decode("seat", String.self))
            case "WaitingForOpponent": return .waitingForOpponent
            case "WrongMatch": return try .wrongMatch(current: fields.decode("current", UInt32.self))
